#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "codici_x.h"

#define GEN_RIGA(nome, num, liv, peso) {STR(nome), (num), (liv), (peso)},
static const info_codice_t TABELLA_CODICI[] = {
    LISTA_CODICI(GEN_RIGA)
};
#undef GEN_RIGA

static_assert(sizeof(TABELLA_CODICI) / sizeof(TABELLA_CODICI[0]) == COD_CONTEGGIO);

LISTA_CODICI(DEF_PRED_CODICE)

static bool trova_per_numero(uint32_t num, size_t *idx_out) {
    for (size_t i = 0; i < COD_CONTEGGIO; ++i) {
        if (TABELLA_CODICI[i].numero == num) {
            *idx_out = i;
            return true;
        }
    }
    return false;
}

int main(void) {
    stats_diag_t st = {};
    char riga[128], cmd[16], tag[24], msg[128], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        unsigned int num = 0, molt = 0;
        if (strcmp(cmd, "REG") == 0 && sscanf(riga, "REG %u %u %c", &num, &molt, &extra) == 2 &&
            molt >= 1 && molt <= 10) {
            size_t idx = 0;
            if (!trova_per_numero((uint32_t)num, &idx)) {
                printf("CODICE_IGNOTO: %u\n", num);
            } else {
                AGGIORNA_STAT(&st, idx, (uint32_t)molt);
                FORMATTA_DIAG(msg, sizeof(msg), TABELLA_CODICI[idx].livello,
                              "%s(#%" PRIu32 ") x%u", TABELLA_CODICI[idx].simbolo,
                              TABELLA_CODICI[idx].numero, molt);
                printf("%s\n", msg);
            }
        } else if (strcmp(cmd, "PING") == 0 && sscanf(riga, "PING %23s %c", tag, &extra) == 1) {
            FORMATTA_DIAG(msg, sizeof(msg), tag, "battito regolare");
            printf("%s\n", msg);
        } else if (strcmp(cmd, "IS_CRIT") == 0 && sscanf(riga, "IS_CRIT %u %c", &num, &extra) == 1) {
            size_t idx = 0;
            if (!trova_per_numero((uint32_t)num, &idx)) {
                printf("IS_CRIT(%u): IGNOTO\n", num);
            } else {
                bool crit = e_codice_CHECKSUM_KO((codice_diag_t)idx);
                printf("IS_CRIT(%u): %d\n", num, crit ? 1 : 0);
            }
        } else if (strcmp(cmd, "TAB") == 0 && sscanf(riga, "TAB %c", &extra) != 1) {
            for (size_t i = 0; i < COD_CONTEGGIO; ++i) {
                printf("%zu: %s num=%" PRIu32 " liv=%s peso=%" PRIu32 "\n",
                       i, TABELLA_CODICI[i].simbolo, TABELLA_CODICI[i].numero,
                       TABELLA_CODICI[i].livello, TABELLA_CODICI[i].peso);
            }
        } else if (strcmp(cmd, "STATS") == 0 && sscanf(riga, "STATS %c", &extra) != 1) {
            printf("STATS: tot=%" PRIu32 " gravita=%" PRIu32 " [", st.totale, st.gravita_tot);
            for (size_t i = 0; i < COD_CONTEGGIO; ++i) {
                printf("%s%s=%" PRIu32, (i > 0) ? " " : "", TABELLA_CODICI[i].simbolo, st.conteggi[i]);
            }
            printf("]\n");
        } else {
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    return EXIT_SUCCESS;
}

