typedef struct vec2 { double x; double y; } vec2_t;

inline int32_t limita_i32(int32_t x, int32_t lo, int32_t hi) {
    return (x < lo) ? lo : ((x > hi) ? hi : x);
}
inline int64_t limita_i64(int64_t x, int64_t lo, int64_t hi) {
    return (x < lo) ? lo : ((x > hi) ? hi : x);
}
inline double limita_dbl(double x, double lo, double hi) {
    return (x < lo) ? lo : ((x > hi) ? hi : x);
}
inline vec2_t limita_vec2(vec2_t v, vec2_t lo, vec2_t hi) {
    return (vec2_t){limita_dbl(v.x, lo.x, hi.x), limita_dbl(v.y, lo.y, hi.y)};
}
inline int32_t somma_sat_i32(int32_t a, int32_t b) {
    int32_t r = 0;
    if (ckd_add(&r, a, b)) { return (b > 0) ? INT32_MAX : INT32_MIN; }
    return r;
}
inline int64_t somma_sat_i64(int64_t a, int64_t b) {
    int64_t r = 0;
    if (ckd_add(&r, a, b)) { return (b > 0) ? INT64_MAX : INT64_MIN; }
    return r;
}
inline double somma_dbl(double a, double b) { return a + b; }
inline vec2_t somma_vec2(vec2_t a, vec2_t b) { return (vec2_t){a.x + b.x, a.y + b.y}; }

static inline int fmt_i32(int32_t x, char *b, size_t n) { return snprintf(b, n, "%" PRId32, x); }
static inline int fmt_i64(int64_t x, char *b, size_t n) { return snprintf(b, n, "%" PRId64, x); }
static inline int fmt_dbl(double x, char *b, size_t n) { return snprintf(b, n, "%.2f", x); }
static inline int fmt_vec2(vec2_t v, char *b, size_t n) { return snprintf(b, n, "(%.2f,%.2f)", v.x, v.y); }

static inline const int32_t *cerca_i32_const(const int32_t *a, size_t n, int32_t v) {
    for (size_t i = 0; i < n; ++i) { if (a[i] == v) { return &a[i]; } }
    return nullptr;
}
static inline int32_t *cerca_i32_mut(int32_t *a, size_t n, int32_t v) {
    for (size_t i = 0; i < n; ++i) { if (a[i] == v) { return &a[i]; } }
    return nullptr;
}

#define LIMITA(x, lo, hi) \
    _Generic((x), int32_t: limita_i32, int64_t: limita_i64, double: limita_dbl, vec2_t: limita_vec2)((x), (lo), (hi))
#define SOMMA(a, b) \
    _Generic((a), int32_t: somma_sat_i32, int64_t: somma_sat_i64, double: somma_dbl, vec2_t: somma_vec2)((a), (b))
#define FORMATTA(x, b, n) \
    _Generic((x), int32_t: fmt_i32, int64_t: fmt_i64, double: fmt_dbl, vec2_t: fmt_vec2)((x), (b), (n))
#define CERCA_I32(arr, n, v) \
    _Generic((arr), const int32_t *: cerca_i32_const, int32_t *: cerca_i32_mut)((arr), (n), (v))

#endif

