        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        long long a64 = 0, b64 = 0, lo64 = 0, hi64 = 0;
        double ad = 0.0, bd = 0.0, lod = 0.0, hid = 0.0;
        vec2_t va = {}, vb = {}, vlo = {}, vhi = {};
        if (strcmp(cmd, "I32") == 0 && sscanf(riga, "I32 %lld %lld %lld %lld %c", &a64, &b64, &lo64, &hi64, &extra) == 4 &&
