#ifndef ERRORE_JMP_H
#define ERRORE_JMP_H

#include <setjmp.h>
#include <stddef.h>

typedef enum cod_errore {
    ERR_NESSUNO = 0, ERR_SINTASSI, ERR_PARENTESI,
    ERR_DIV_ZERO, ERR_OVERFLOW, ERR_PROFONDITA, ERR_MEMORIA
} cod_errore_t;

typedef struct frame_err {
    jmp_buf env;
    struct frame_err *prec;
    cod_errore_t codice;
    size_t pos;
    void *risorse[8];
    size_t n_risorse;
} frame_err_t;

void err_push(frame_err_t *f);
void err_pop(frame_err_t *f);
bool err_traccia(void *ptr);
void err_rilascia_risorse(frame_err_t *f);
[[noreturn]] void err_lancia(cod_errore_t cod, size_t pos);
const char *err_nome(cod_errore_t cod);

#endif

