#include "errore_jmp.h"
#include <stdlib.h>

static frame_err_t *corrente = nullptr;

void err_push(frame_err_t *f) {
    f->prec = corrente;
    f->codice = ERR_NESSUNO;
    f->pos = 0;
    f->n_risorse = 0;
    corrente = f;
}

void err_pop(frame_err_t *f) {
    if (corrente == f) { corrente = f->prec; }
}

bool err_traccia(void *ptr) {
    if (ptr == nullptr || corrente == nullptr || corrente->n_risorse >= 8) { return false; }
    corrente->risorse[corrente->n_risorse++] = ptr;
    return true;
}

void err_rilascia_risorse(frame_err_t *f) {
    if (f == nullptr) { return; }
    for (size_t i = f->n_risorse; i > 0; --i) { free(f->risorse[i - 1]); }
    f->n_risorse = 0;
}

[[noreturn]] void err_lancia(cod_errore_t cod, size_t pos) {
    if (corrente == nullptr) { abort(); }
    corrente->codice = cod;
    corrente->pos = pos;
    longjmp(corrente->env, 1);
}

const char *err_nome(cod_errore_t cod) {
    switch (cod) {
        case ERR_SINTASSI: return "SINTASSI";
        case ERR_PARENTESI: return "PARENTESI";
        case ERR_DIV_ZERO: return "DIV_ZERO";
        case ERR_OVERFLOW: return "OVERFLOW";
        case ERR_PROFONDITA: return "PROFONDITA";
        case ERR_MEMORIA: return "MEMORIA";
        default: return "NESSUNO";
    }
}

