#include <ctype.h>
#include <inttypes.h>
#include <stdckdint.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "errore_jmp.h"

typedef struct parser { const char *s; size_t pos; int prof; } parser_t;

static void salta_spazi(parser_t *p) {
    while (isspace((unsigned char)p->s[p->pos])) { ++p->pos; }
}
static int64_t parse_expr(parser_t *p);

static int64_t parse_fattore(parser_t *p) {
    salta_spazi(p);
    if (p->s[p->pos] == '-') {
        size_t pos_m = p->pos++;
        int64_t v = parse_fattore(p), r = 0;
        if (ckd_sub(&r, (int64_t)0, v)) { err_lancia(ERR_OVERFLOW, pos_m); }
        return r;
    }
    if (p->s[p->pos] == '(') {
        if (p->prof >= 8) { err_lancia(ERR_PROFONDITA, p->pos); }
        ++p->pos; ++p->prof;
        int64_t v = parse_expr(p);
        salta_spazi(p);
        if (p->s[p->pos] != ')') { err_lancia(ERR_PARENTESI, p->pos); }
        ++p->pos; --p->prof;
        return v;
    }
    if (!isdigit((unsigned char)p->s[p->pos])) { err_lancia(ERR_SINTASSI, p->pos); }
    int64_t acc = 0;
    while (isdigit((unsigned char)p->s[p->pos])) {
        int64_t d = p->s[p->pos] - '0';
        if (ckd_mul(&acc, acc, (int64_t)10) || ckd_add(&acc, acc, d)) { err_lancia(ERR_OVERFLOW, p->pos); }
        ++p->pos;
    }
    return acc;
}

static int64_t parse_termine(parser_t *p) {
    int64_t sx = parse_fattore(p);
    while (true) {
        salta_spazi(p);
        char op = p->s[p->pos];
        if (op != '*' && op != '/') { break; }
        size_t pos_op = p->pos++;
        int64_t dx = parse_fattore(p), r = 0;
        if (op == '*') {
            if (ckd_mul(&r, sx, dx)) { err_lancia(ERR_OVERFLOW, pos_op); }
        } else {
            if (dx == 0) { err_lancia(ERR_DIV_ZERO, pos_op); }
            if (sx == INT64_MIN && dx == -1) { err_lancia(ERR_OVERFLOW, pos_op); }
            r = sx / dx;
        }
        sx = r;
    }
    return sx;
}

static int64_t parse_expr(parser_t *p) {
    int64_t sx = parse_termine(p);
    while (true) {
        salta_spazi(p);
        char op = p->s[p->pos];
        if (op != '+' && op != '-') { break; }
        size_t pos_op = p->pos++;
        int64_t dx = parse_termine(p), r = 0;
        if ((op == '+' && ckd_add(&r, sx, dx)) || (op == '-' && ckd_sub(&r, sx, dx))) {
            err_lancia(ERR_OVERFLOW, pos_op);
        }
        sx = r;
    }
    return sx;
}

static int64_t valuta_copia(const char *testo, size_t len) {
    char *copia = malloc(len + 1);
    if (copia == nullptr || !err_traccia(copia)) { free(copia); err_lancia(ERR_MEMORIA, 0); }
    memcpy(copia, testo, len);
    copia[len] = '\0';
    parser_t p = {.s = copia, .pos = 0, .prof = 0};
    int64_t ris = parse_expr(&p);
    salta_spazi(&p);
    if (p.s[p.pos] != '\0') { err_lancia(ERR_SINTASSI, p.pos); }
    return ris;
}

static void gestisci_try(const char *e1, size_t l1, const char *e2, size_t l2,
                         size_t *ok, size_t *fb, size_t *err) {
    frame_err_t ext = {};
    volatile int fase = 0;
    volatile cod_errore_t causa_fb = ERR_NESSUNO;
    err_push(&ext);
    if (setjmp(ext.env) == 0) {
        frame_err_t inn = {};
        err_push(&inn);
        if (setjmp(inn.env) == 0) {
            fase = 1;
            int64_t v = valuta_copia(e1, l1);
            err_rilascia_risorse(&inn); err_pop(&inn);
            err_rilascia_risorse(&ext); err_pop(&ext);
            printf("TRY -> OK %" PRId64 "\n", v);
            ++(*ok);
        } else {
            cod_errore_t c = inn.codice; size_t pos = inn.pos;
            err_rilascia_risorse(&inn); err_pop(&inn);
            if (c != ERR_DIV_ZERO && c != ERR_OVERFLOW) { err_lancia(c, pos); }
            causa_fb = c;
            fase = 2;
            int64_t v2 = valuta_copia(e2, l2);
            err_rilascia_risorse(&ext); err_pop(&ext);
            printf("TRY -> FALLBACK(%s) OK %" PRId64 "\n", err_nome(causa_fb), v2);
            ++(*fb);
        }
    } else {
        cod_errore_t c = ext.codice; size_t pos = ext.pos;
        err_rilascia_risorse(&ext); err_pop(&ext);
        printf("TRY -> %s %s pos=%zu\n", (fase == 2) ? "ERRORE_FALLBACK" : "ERRORE", err_nome(c), pos);
        ++(*err);
    }
}

int main(void) {
    char riga[256];
    size_t tot_ok = 0, tot_fb = 0, tot_err = 0;
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        size_t len = strlen(riga);
        while (len > 0 && (riga[len - 1] == '\n' || riga[len - 1] == '\r')) { riga[--len] = '\0'; }
        if (len == 0) { continue; }
        if (strncmp(riga, "EVAL ", 5) == 0) {
            frame_err_t f = {};
            err_push(&f);
            if (setjmp(f.env) == 0) {
                int64_t v = valuta_copia(riga + 5, len - 5);
                err_rilascia_risorse(&f); err_pop(&f);
                printf("EVAL -> OK %" PRId64 "\n", v); ++tot_ok;
            } else {
                cod_errore_t c = f.codice; size_t pos = f.pos;
                err_rilascia_risorse(&f); err_pop(&f);
                printf("EVAL -> ERRORE %s pos=%zu\n", err_nome(c), pos); ++tot_err;
            }
        } else if (strncmp(riga, "TRY ", 4) == 0) {
            const char *sep = strchr(riga + 4, '|');
            if (sep == nullptr) { return EXIT_FAILURE; }
            const char *e1 = riga + 4, *e2 = sep + 1;
            size_t l1 = (size_t)(sep - e1), l2 = strlen(e2);
            while (l1 > 0 && isspace((unsigned char)e1[l1 - 1])) { --l1; }
