#include "lista_intr.h"

void lista_init(nodo_intrusivo_t *n) {
    n->prev = n;
    n->next = n;
}

bool lista_vuota(const nodo_intrusivo_t *testa) { return testa->next == testa; }
bool lista_collegato(const nodo_intrusivo_t *n) { return n->next != n; }

static void inserisci_tra(nodo_intrusivo_t *a, nodo_intrusivo_t *b, nodo_intrusivo_t *n) {
    n->prev = a; n->next = b;
    a->next = n; b->prev = n;
}

void lista_inserisci_testa(nodo_intrusivo_t *testa, nodo_intrusivo_t *n) {
    inserisci_tra(testa, testa->next, n);
}

void lista_inserisci_coda(nodo_intrusivo_t *testa, nodo_intrusivo_t *n) {
    inserisci_tra(testa->prev, testa, n);
}

void lista_rimuovi(nodo_intrusivo_t *n) {
    if (!lista_collegato(n)) { return; }
    n->prev->next = n->next;
    n->next->prev = n->prev;
    lista_init(n);
}

size_t lista_conta(const nodo_intrusivo_t *testa) {
    size_t c = 0;
    LISTA_PER_OGNI_CONST(pos, testa) { (void)pos; ++c; }
    return c;
}

