#include "lista_intr.h"

typedef struct lavoro {
    uint32_t id;
    char nome[16];
    int prio;
    bool pronto;
    nodo_intrusivo_t link_tutti;
    nodo_intrusivo_t link_pronti;
} lavoro_t;

static lavoro_t *cerca_lavoro(nodo_intrusivo_t *tutti, uint32_t id) {
    LISTA_PER_OGNI(pos, tutti) {
        lavoro_t *l = CONTENITORE_DI(pos, lavoro_t, link_tutti);
        if (l->id == id) { return l; }
    }
    return nullptr;
}

static void accoda_pronto(nodo_intrusivo_t *pronti, lavoro_t *l) {
    if (l->prio >= 10) { lista_inserisci_testa(pronti, &l->link_pronti); }
    else { lista_inserisci_coda(pronti, &l->link_pronti); }
    l->pronto = true;
}

static void stampa_liste(const nodo_intrusivo_t *tutti, const nodo_intrusivo_t *pronti) {
    printf("TUTTI(%zu):", lista_conta(tutti));
    if (lista_vuota(tutti)) { printf(" (vuota)\n"); }
    else {
        LISTA_PER_OGNI_CONST(pos, tutti) {
            const lavoro_t *l = CONTENITORE_DI_CONST(pos, lavoro_t, link_tutti);
            printf(" #%" PRIu32 ":%s(%c)", l->id, l->nome, l->pronto ? 'P' : 'S');
        }
        printf("\n");
    }
    printf("PRONTI(%zu):", lista_conta(pronti));
    if (lista_vuota(pronti)) { printf(" (vuota)\n"); }
    else {
        LISTA_PER_OGNI_CONST(pos, pronti) {
            const lavoro_t *l = CONTENITORE_DI_CONST(pos, lavoro_t, link_pronti);
            printf(" #%" PRIu32 ":%s", l->id, l->nome);
        }
        printf("\n");
    }
}

int main(void) {
    nodo_intrusivo_t tutti, pronti;
    lista_init(&tutti); lista_init(&pronti);
    char riga[128], cmd[16], nome[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        unsigned int id = 0; int prio = 0;
        if (strcmp(cmd, "ADD") == 0 && sscanf(riga, "ADD %u %15s %d %c", &id, nome, &prio, &extra) == 3) {
            lavoro_t *l = calloc(1, sizeof(*l));
            if (l == nullptr) { return EXIT_FAILURE; }
            l->id = (uint32_t)id; l->prio = prio;
            snprintf(l->nome, sizeof(l->nome), "%s", nome);
            lista_init(&l->link_tutti); lista_init(&l->link_pronti);
            lista_inserisci_coda(&tutti, &l->link_tutti);
            accoda_pronto(&pronti, l);
        } else if (strcmp(cmd, "PAUSE") == 0 && sscanf(riga, "PAUSE %u %c", &id, &extra) == 1) {
            lavoro_t *l = cerca_lavoro(&tutti, (uint32_t)id);
            if (l == nullptr) { printf("PAUSE #%u: ASSENTE\n", id); }
            else { lista_rimuovi(&l->link_pronti); l->pronto = false; }
        } else if (strcmp(cmd, "RESUME") == 0 && sscanf(riga, "RESUME %u %c", &id, &extra) == 1) {
            lavoro_t *l = cerca_lavoro(&tutti, (uint32_t)id);
            if (l == nullptr) { printf("RESUME #%u: ASSENTE\n", id); }
            else if (!l->pronto) { accoda_pronto(&pronti, l); }
        } else if (strcmp(cmd, "DEL") == 0 && sscanf(riga, "DEL %u %c", &id, &extra) == 1) {
            lavoro_t *l = cerca_lavoro(&tutti, (uint32_t)id);
            if (l == nullptr) { printf("DEL #%u: ASSENTE\n", id); }
            else { lista_rimuovi(&l->link_pronti); lista_rimuovi(&l->link_tutti); free(l); printf("DEL #%u: OK\n", id); }
        } else if (strcmp(cmd, "PURGE_PAUSED") == 0 && sscanf(riga, "PURGE_PAUSED %c", &extra) != 1) {
            size_t rim = 0;
            LISTA_PER_OGNI_SICURO(pos, tmp, &tutti) {
                lavoro_t *l = CONTENITORE_DI(pos, lavoro_t, link_tutti);
                if (!l->pronto) { lista_rimuovi(&l->link_tutti); free(l); ++rim; }
            }
            printf("PURGE_PAUSED: rimossi=%zu\n", rim);
        } else if (strcmp(cmd, "SHOW") == 0 && sscanf(riga, "SHOW %c", &extra) != 1) {
            stampa_liste(&tutti, &pronti);
        } else { return EXIT_FAILURE; }
    }
    LISTA_PER_OGNI_SICURO(pos, tmp, &tutti) {
        lavoro_t *l = CONTENITORE_DI(pos, lavoro_t, link_tutti);
        lista_rimuovi(&l->link_pronti); lista_rimuovi(&l->link_tutti); free(l);
    }
    return EXIT_SUCCESS;
}

