struct fsm_sess {
    stato_sess_t stato;
    uint32_t err_auth, sessioni_ok, blocchi, pacchetti, rifiutati;
    uint64_t byte_tx;
};

typedef stato_sess_t (*azione_fn)(fsm_sess_t *f, int32_t payload, stato_sess_t def_st, bool *ok);
typedef void (*enter_fn)(fsm_sess_t *f);
typedef struct transizione { bool valida; stato_sess_t prossimo; azione_fn azione; } transizione_t;

static const char *const NOMI_STATO[] = {"CHIUSA", "HANDSHAKE", "AUTH", "ATTIVA", "BLOCCATA"};
static_assert(sizeof(NOMI_STATO) / sizeof(NOMI_STATO[0]) == ST_CONTEGGIO);

static void enter_attiva(fsm_sess_t *f) { ++f->sessioni_ok; }
static void enter_bloccata(fsm_sess_t *f) { ++f->blocchi; }
static const enter_fn ON_ENTER[] = {nullptr, nullptr, nullptr, enter_attiva, enter_bloccata};
static_assert(sizeof(ON_ENTER) / sizeof(ON_ENTER[0]) == ST_CONTEGGIO);

static stato_sess_t az_azzera_err(fsm_sess_t *f, int32_t p, stato_sess_t d, bool *ok) {
    (void)p; (void)ok; f->err_auth = 0; return d;
}
static stato_sess_t az_auth_ko(fsm_sess_t *f, int32_t p, stato_sess_t d, bool *ok) {
    (void)p; (void)ok; ++f->err_auth;
    return (f->err_auth >= 3) ? ST_BLOCCATA : d;
}
static stato_sess_t az_dato(fsm_sess_t *f, int32_t p, stato_sess_t d, bool *ok) {
    if (p <= 0) { *ok = false; ++f->rifiutati; return f->stato; }
    ++f->pacchetti; f->byte_tx += (uint64_t)p; return d;
}

static const transizione_t TABELLA[ST_CONTEGGIO][EV_CONTEGGIO] = {
    [ST_CHIUSA]    = { [EV_APRI]    = {true, ST_HANDSHAKE, nullptr} },
    [ST_HANDSHAKE] = { [EV_ACK]     = {true, ST_AUTH, az_azzera_err},
                       [EV_CHIUDI]  = {true, ST_CHIUSA, nullptr} },
    [ST_AUTH]      = { [EV_AUTH_OK] = {true, ST_ATTIVA, az_azzera_err},
                       [EV_AUTH_KO] = {true, ST_AUTH, az_auth_ko},
                       [EV_CHIUDI]  = {true, ST_CHIUSA, nullptr} },
    [ST_ATTIVA]    = { [EV_DATO]    = {true, ST_ATTIVA, az_dato},
                       [EV_CHIUDI]  = {true, ST_CHIUSA, nullptr} },
    [ST_BLOCCATA]  = { [EV_RESET]   = {true, ST_CHIUSA, az_azzera_err} }
};

fsm_sess_t *fsm_crea(void) { return calloc(1, sizeof(fsm_sess_t)); }
void fsm_distruggi(fsm_sess_t *f) { free(f); }
stato_sess_t fsm_stato(const fsm_sess_t *f) { return (f != nullptr) ? f->stato : ST_CHIUSA; }
const char *fsm_nome_stato(stato_sess_t s) { return (s < ST_CONTEGGIO) ? NOMI_STATO[s] : "IGNOTO"; }

bool fsm_invia(fsm_sess_t *f, evento_sess_t ev, int32_t payload) {
    if (f == nullptr || f->stato >= ST_CONTEGGIO || ev >= EV_CONTEGGIO) { return false; }
    const transizione_t *t = &TABELLA[f->stato][ev];
    if (!t->valida) { ++f->rifiutati; return false; }
    stato_sess_t vecchio = f->stato;
    bool ok = true;
    stato_sess_t nuovo = (t->azione != nullptr) ? t->azione(f, payload, t->prossimo, &ok) : t->prossimo;
    if (!ok) { return false; }
    f->stato = nuovo;
    if (nuovo != vecchio && ON_ENTER[nuovo] != nullptr) { ON_ENTER[nuovo](f); }
    return true;
}

void fsm_stampa_stats(const fsm_sess_t *f) {
    printf("STATS: stato=%s sess_ok=%" PRIu32 " blocchi=%" PRIu32 " pkt=%" PRIu32 " byte=%" PRIu64 " rifiutati=%" PRIu32 "\n",
           fsm_nome_stato(f->stato), f->sessioni_ok, f->blocchi, f->pacchetti, f->byte_tx, f->rifiutati);
}

