#include "frame_bin.h"

static size_t len_attesa(unsigned int tipo) {
    if (tipo == FRM_PING) { return 0; }
    if (tipo == FRM_SENSORE) { return 4; }
    return 2;
}

static int16_t u16_a_i16(uint16_t u) {
    if ((u & 0x8000U) == 0U) { return (int16_t)u; }
    return (u == 0x8000U) ? INT16_MIN : (int16_t)(-(int32_t)(uint16_t)((uint16_t)(~u) + 1U));
}

uint8_t frame_crc8(const uint8_t *buf, size_t n) {
    uint8_t crc = 0;
    for (size_t i = 0; i < n; ++i) {
        crc ^= buf[i];
        for (int b = 0; b < 8; ++b) {
            crc = ((crc & 0x80U) != 0U) ? (uint8_t)((crc << 1) ^ 0x07U) : (uint8_t)(crc << 1);
        }
    }
    return crc;
}

size_t frame_codifica(const frame_t *f, uint8_t *out, size_t cap) {
    if (f == nullptr || out == nullptr) { return 0; }
    size_t plen = len_attesa(f->hdr.tipo);
    if (f->hdr.len != plen || cap < 5 + plen) { return 0; }
    uint32_t w = ((uint32_t)f->hdr.versione << 30) | ((uint32_t)f->hdr.tipo << 28) |
                 ((uint32_t)f->hdr.priorita << 26) | ((uint32_t)f->hdr.cifrato << 25) |
                 ((uint32_t)f->hdr.ack << 24) | ((uint32_t)f->hdr.src << 18) |
                 ((uint32_t)f->hdr.dst << 12) | ((uint32_t)f->hdr.len << 8) | (uint32_t)f->hdr.seq;
    out[0] = (uint8_t)(w >> 24); out[1] = (uint8_t)(w >> 16);
    out[2] = (uint8_t)(w >> 8);  out[3] = (uint8_t)w;
    if (f->hdr.tipo == FRM_SENSORE) {
        uint16_t tu = (uint16_t)f->dati.sensore.temp_d;
        out[4] = (uint8_t)(tu >> 8); out[5] = (uint8_t)tu;
        out[6] = (uint8_t)(f->dati.sensore.umid_d >> 8); out[7] = (uint8_t)f->dati.sensore.umid_d;
    } else if (f->hdr.tipo == FRM_COMANDO) {
        out[4] = f->dati.comando.op; out[5] = f->dati.comando.arg;
    } else if (f->hdr.tipo == FRM_ERRORE) {
        out[4] = (uint8_t)(f->dati.errore.cod >> 8); out[5] = (uint8_t)f->dati.errore.cod;
    }
    out[4 + plen] = frame_crc8(out, 4 + plen);
    return 5 + plen;
}

esito_frame_t frame_decodifica(const uint8_t *buf, size_t n, frame_t *out) {
    if (buf == nullptr || out == nullptr || n < 5 || n > 9) { return FRM_ERR_LEN; }
    if (frame_crc8(buf, n - 1) != buf[n - 1]) { return FRM_ERR_CRC; }
    uint32_t w = ((uint32_t)buf[0] << 24) | ((uint32_t)buf[1] << 16) |
                 ((uint32_t)buf[2] << 8) | (uint32_t)buf[3];
    *out = (frame_t){ .hdr = {
        .versione = (w >> 30) & 3U, .tipo = (w >> 28) & 3U, .priorita = (w >> 26) & 3U,
        .cifrato = (w >> 25) & 1U, .ack = (w >> 24) & 1U, .src = (w >> 18) & 0x3FU,
        .dst = (w >> 12) & 0x3FU, .len = (w >> 8) & 0x0FU, .seq = w & 0xFFU
    }};
    if (out->hdr.versione != 1U) { return FRM_ERR_VER; }
    size_t plen = len_attesa(out->hdr.tipo);
    if (out->hdr.len != plen) { return FRM_ERR_PAYLOAD; }
    if (n != 5 + plen) { return FRM_ERR_LEN; }
    if (out->hdr.tipo == FRM_SENSORE) {
        out->dati.sensore.temp_d = u16_a_i16((uint16_t)(((uint16_t)buf[4] << 8) | buf[5]));
        out->dati.sensore.umid_d = (uint16_t)(((uint16_t)buf[6] << 8) | buf[7]);
    } else if (out->hdr.tipo == FRM_COMANDO) {
        out->dati.comando.op = buf[4]; out->dati.comando.arg = buf[5];
    } else if (out->hdr.tipo == FRM_ERRORE) {
        out->dati.errore.cod = (uint16_t)(((uint16_t)buf[4] << 8) | buf[5]);
    }
    return FRM_OK;
}

