    printf("DEC OK: v=%u %s prio=%u cif=%u ack=%u %u->%u seq=%u",
           f->hdr.versione, NT[f->hdr.tipo], f->hdr.priorita, f->hdr.cifrato,
           f->hdr.ack, f->hdr.src, f->hdr.dst, f->hdr.seq);
    if (f->hdr.tipo == FRM_SENSORE) {
        printf(" temp=%" PRId16 " umid=%" PRIu16, f->dati.sensore.temp_d, f->dati.sensore.umid_d);
    } else if (f->hdr.tipo == FRM_COMANDO) {
        printf(" op=%" PRIu8 " arg=%" PRIu8, f->dati.comando.op, f->dati.comando.arg);
    } else if (f->hdr.tipo == FRM_ERRORE) {
        printf(" cod=%" PRIu16, f->dati.errore.cod);
    }
    printf("\n");
}

int main(void) {
    char riga[256], cmd[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        unsigned int pr = 0, ci = 0, ak = 0, sr = 0, ds = 0, sq = 0, u1 = 0, u2 = 0;
        int s1 = 0;
        uint8_t raw[16] = {};
        if (strcmp(cmd, "ENC_PING") == 0 && sscanf(riga, "ENC_PING %u %u %u %u %u %u %c", &pr, &ci, &ak, &sr, &ds, &sq, &extra) == 6) {
            frame_t f = {.hdr = {1, FRM_PING, pr, ci, ak, sr, ds, 0, sq}};
            stampa_hex(raw, frame_codifica(&f, raw, sizeof(raw)));
        } else if (strcmp(cmd, "ENC_SENS") == 0 && sscanf(riga, "ENC_SENS %u %u %u %u %u %u %d %u %c", &pr, &ci, &ak, &sr, &ds, &sq, &s1, &u2, &extra) == 8) {
            frame_t f = {.hdr = {1, FRM_SENSORE, pr, ci, ak, sr, ds, 4, sq}, .dati = {.sensore = {(int16_t)s1, (uint16_t)u2}}};
            stampa_hex(raw, frame_codifica(&f, raw, sizeof(raw)));
        } else if (strcmp(cmd, "ENC_CMD") == 0 && sscanf(riga, "ENC_CMD %u %u %u %u %u %u %u %u %c", &pr, &ci, &ak, &sr, &ds, &sq, &u1, &u2, &extra) == 8) {
            frame_t f = {.hdr = {1, FRM_COMANDO, pr, ci, ak, sr, ds, 2, sq}, .dati = {.comando = {(uint8_t)u1, (uint8_t)u2}}};
            stampa_hex(raw, frame_codifica(&f, raw, sizeof(raw)));
        } else if (strcmp(cmd, "ENC_ERR") == 0 && sscanf(riga, "ENC_ERR %u %u %u %u %u %u %u %c", &pr, &ci, &ak, &sr, &ds, &sq, &u1, &extra) == 7) {
            frame_t f = {.hdr = {1, FRM_ERRORE, pr, ci, ak, sr, ds, 2, sq}, .dati = {.errore = {(uint16_t)u1}}};
            stampa_hex(raw, frame_codifica(&f, raw, sizeof(raw)));
        } else if (strcmp(cmd, "DEC") == 0) {
            size_t n = 0; int pos = 0;
            if (sscanf(riga, "DEC %zu%n", &n, &pos) != 1 || n > 16) { return EXIT_FAILURE; }
            const char *p = riga + pos;
            for (size_t i = 0; i < n; ++i) {
                unsigned int v = 0; int av = 0;
                if (sscanf(p, "%x%n", &v, &av) != 1 || v > 255) { return EXIT_FAILURE; }
                raw[i] = (uint8_t)v; p += av;
            }
            frame_t f = {};
            esito_frame_t e = frame_decodifica(raw, n, &f);
            if (e == FRM_OK) { stampa_frame(&f); }
            else {
                static const char *const NE[] = {"OK", "LEN", "CRC", "VER", "PAYLOAD"};
                printf("DEC ERR: %s\n", NE[e]);
            }
        } else { return EXIT_FAILURE; }
    }
    return EXIT_SUCCESS;
}
